1  import {useFocusEffect} from '@react-navigation/native';
     2  import type {StackScreenProps} from '@react-navigation/stack';
     3  import React, {useCallback, useMemo, useState} from 'react';
     4  import {ActivityIndicator, View} from 'react-native';
     5  import {useOnyx} from 'react-native-onyx';
     6  import ApprovalWorkflowSection from '@components/ApprovalWorkflowSection';
     7  import ConfirmModal from '@components/ConfirmModal';
     8  import getBankIcon from '@components/Icon/BankIcons';
     9  import type {BankName} from '@components/Icon/BankIconsUtils';
    10  import * as Expensicons from '@components/Icon/Expensicons';
    11  import * as Illustrations from '@components/Icon/Illustrations';
    12  import MenuItem from '@components/MenuItem';
    13  import MenuItemWithTopDescription from '@components/MenuItemWithTopDescription';
    14  import OfflineWithFeedback from '@components/OfflineWithFeedback';
    15  import Section from '@components/Section';
    16  import Text from '@components/Text';
    17  import Permissions from '@libs/Permissions';
    18  import useLocalize from '@hooks/useLocalize';
    19  import useNetwork from '@hooks/useNetwork';
    20  import useResponsiveLayout from '@hooks/useResponsiveLayout';
    21  import useTheme from '@hooks/useTheme';
    22  import useThemeStyles from '@hooks/useThemeStyles';
    23  import * as ErrorUtils from '@libs/ErrorUtils';
    24  import Navigation from '@libs/Navigation/Navigation';
    25  import {getPaymentMethodDescription} from '@libs/PaymentUtils';
    26  import * as PersonalDetailsUtils from '@libs/PersonalDetailsUtils';
    27  import * as PolicyUtils from '@libs/PolicyUtils';
    28  import {convertPolicyEmployeesToApprovalWorkflows, INITIAL_APPROVAL_WORKFLOW} from '@libs/WorkflowUtils';
    29  import type {FullScreenNavigatorParamList} from '@navigation/types';
    30  import AccessOrNotFoundWrapper from '@pages/workspace/AccessOrNotFoundWrapper';
    31  import type {WithPolicyProps} from '@pages/workspace/withPolicy';
    32  import withPolicy from '@pages/workspace/withPolicy';
    33  import WorkspacePageWithSections from '@pages/workspace/WorkspacePageWithSections';
    34  import * as Policy from '@userActions/Policy/Policy';
    35  import {navigateToBankAccountRoute} from '@userActions/ReimbursementAccount';
    36  import * as Workflow from '@userActions/Workflow';
    37  import CONST from '@src/CONST';
    38  import ONYXKEYS from '@src/ONYXKEYS';
    39  import ROUTES from '@src/ROUTES';
    40  import type SCREENS from '@src/SCREENS';
    41  import ToggleSettingOptionRow from './ToggleSettingsOptionRow';
    42  import type {ToggleSettingOptionRowProps} from './ToggleSettingsOptionRow';
    43  import {getAutoReportingFrequencyDisplayNames} from './WorkspaceAutoReportingFrequencyPage';
    44  import type {AutoReportingFrequencyKey} from './WorkspaceAutoReportingFrequencyPage';
    45
    46  type WorkspaceWorkflowsPageOnyxProps = {
    47      /** Beta features list */
    48      betas: OnyxEntry<Beta[]>;
    49  };
    50  type WorkspaceWorkflowsPageProps = WithPolicyProps & WorkspaceWorkflowsPageOnyxProps & StackScreenProps<FullScreenNavigatorParamList, typeof SCREENS.WORKSPACE.WORKFLOWS>;
    51  function WorkspaceWorkflowsPage({policy, betas, route}: WorkspaceWorkflowsPageProps) {
    52      const {translate, preferredLocale} = useLocalize();
    53      const theme = useTheme();
    54      const styles = useThemeStyles();
    55      const {shouldUseNarrowLayout, isSmallScreenWidth} = useResponsiveLayout();
    56      const canUseDelayedSubmission = Permissions.canUseWorkflowsDelayedSubmission(betas);
    57      const policyApproverEmail = policy?.approver;
    58      const [isCurrencyModalOpen, setIsCurrencyModalOpen] = useState(false);
    59      const [personalDetails] = useOnyx(ONYXKEYS.PERSONAL_DETAILS_LIST);
    60      const policyApproverName = useMemo(() => PersonalDetailsUtils.getPersonalDetailByEmail(policyApproverEmail ?? '')?.displayName ?? policyApproverEmail, [policyApproverEmail]);
    61      const containerStyle = useMemo(() => [styles.ph8, styles.mhn8, styles.ml11, styles.pv3, styles.pr0, styles.pl4, styles.mr0, styles.widthAuto, styles.mt4], [styles]);
    62      const {approvalWorkflows, availableMembers, usedApproverEmails} = useMemo(
    63          () =>
    64              convertPolicyEmployeesToApprovalWorkflows({
    65                  employees: policy?.employeeList ?? {},
    66                  defaultApprover: policyApproverEmail ?? policy?.owner ?? '',
    67                  personalDetails: personalDetails ?? {},
    68              }),
    69          [personalDetails, policy?.employeeList, policy?.owner, policyApproverEmail],
    70      );
    71      const displayNameForAuthorizedPayer = useMemo(
    72          () => PersonalDetailsUtils.getPersonalDetailByEmail(policy?.achAccount?.reimburser ?? '')?.displayName ?? policy?.achAccount?.reimburser,
    73          [policy?.achAccount?.reimburser],
    74      );
    75
    76      const onPressAutoReportingFrequency = useCallback(() => Navigation.navigate(ROUTES.WORKSPACE_WORKFLOWS_AUTOREPORTING_FREQUENCY.getRoute(route.params.policyID)), [route.params.policyID]);
    77
    78      const fetchData = useCallback(() => {
    79          Policy.openPolicyWorkflowsPage(route.params.policyID);
    80      }, [route.params.policyID]);
    81
    82      const confirmCurrencyChangeAndHideModal = useCallback(() => {
    83          if (!policy) {
    84              return;
    85          }
    86          Policy.updateGeneralSettings(policy.id, policy.name, CONST.CURRENCY.USD);
    87          setIsCurrencyModalOpen(false);
    88          navigateToBankAccountRoute(route.params.policyID, ROUTES.WORKSPACE_WORKFLOWS.getRoute(route.params.policyID));
    89      }, [policy, route.params.policyID]);
    90
    91      const {isOffline} = useNetwork({onReconnect: fetchData});
    92      const isPolicyAdmin = PolicyUtils.isPolicyAdmin(policy);
    93
    94      useFocusEffect(
    95          useCallback(() => {
    96              fetchData();
    97          }, [fetchData]),
    98      );
    99
   100      // User should be allowed to add new Approval Workflow only if he's upgraded to Control Plan, otherwise redirected to the Upgrade Page
   101      const addApprovalAction = useCallback(() => {
   102          if (!PolicyUtils.isControlPolicy(policy)) {
   103              Navigation.navigate(
   104                  ROUTES.WORKSPACE_UPGRADE.getRoute(route.params.policyID, CONST.UPGRADE_FEATURE_INTRO_MAPPING.approvals.alias, ROUTES.WORKSPACE_WORKFLOWS.getRoute(route.params.policyID)),
   105              );
   106              return;
   107          }
   108
   109          Workflow.setApprovalWorkflow({
   110              ...INITIAL_APPROVAL_WORKFLOW,
   111              availableMembers,
   112              usedApproverEmails,
   113          });
   114          Navigation.navigate(ROUTES.WORKSPACE_WORKFLOWS_APPROVALS_EXPENSES_FROM.getRoute(route.params.policyID));
   115      }, [policy, route.params.policyID, availableMembers, usedApproverEmails]);
   116
   117      const optionItems: ToggleSettingOptionRowProps[] = useMemo(() => {
   118          const {accountNumber, addressName, bankName, bankAccountID} = policy?.achAccount ?? {};
   119          const shouldShowBankAccount = !!bankAccountID && policy?.reimbursementChoice === CONST.POLICY.REIMBURSEMENT_CHOICES.REIMBURSEMENT_YES;
   120          let bankDisplayName = bankName ?? addressName;
   121          if (accountNumber && bankDisplayName !== accountNumber) {
   122              bankDisplayName += ` ${accountNumber.slice(-5)}`;
   123          }
   124          const hasReimburserError = !!policy?.errorFields?.reimburser;
   125          const hasApprovalError = !!policy?.errorFields?.approvalMode;
   126          const hasDelayedSubmissionError = !!policy?.errorFields?.autoReporting;
   127          return [
   128              ...(canUseDelayedSubmission
   129                  ? [
   130                        {
   131                            icon: Illustrations.ReceiptEnvelope,
   132                            title: translate('workflowsPage.delaySubmissionTitle'),
   133                            subtitle: translate('workflowsPage.delaySubmissionDescription'),
   134                            switchAccessibilityLabel: translate('workflowsPage.delaySubmissionDescription'),
   135                            onToggle: (isEnabled: boolean) => {
   136                                Policy.setWorkspaceAutoReportingFrequency(
   137                                    route.params.policyID,
   138                                    isEnabled ? CONST.POLICY.AUTO_REPORTING_FREQUENCIES.WEEKLY : CONST.POLICY.AUTO_REPORTING_FREQUENCIES.INSTANT,
   139                                );
   140                            },
   141                            subMenuItems: (
   142                                <MenuItem
   143                                    title={translate('workflowsPage.submissionFrequency')}
   144                                    titleStyle={styles.textLabelSupportingNormal}
   145                                    descriptionTextStyle={styles.textNormalThemeText}
   146                                    onPress={onPressAutoReportingFrequency}
   147                                    // Instant submit is the equivalent of delayed submissions being turned off, so we show the feature as disabled if the frequency is instant
   148                                    description={
   149                                        getAutoReportingFrequencyDisplayNames(preferredLocale)[
   150                                            (policy?.autoReportingFrequency as AutoReportingFrequencyKey) ?? CONST.POLICY.AUTO_REPORTING_FREQUENCIES.WEEKLY
   151                                        ]
   152                                    }
   153                                    shouldShowRightIcon
   154                                     wrapperStyle={containerStyle}
   155                                    hoverAndPressStyle={[styles.mr0, styles.br2]}
   156                                    brickRoadIndicator={hasDelayedSubmissionError ? CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR : undefined}
   157                                />
   158                            ),
   159                            isActive: (policy?.harvesting?.enabled && policy.autoReportingFrequency !== CONST.POLICY.AUTO_REPORTING_FREQUENCIES.INSTANT && !hasDelayedSubmissionError) ?? false,
   160                            pendingAction: policy?.pendingFields?.autoReporting,
   161                            errors: ErrorUtils.getLatestErrorField(policy ?? {}, CONST.POLICY.COLLECTION_KEYS.AUTOREPORTING),
   162                            onCloseError: () => Policy.clearPolicyErrorField(policy?.id ?? '-1', CONST.POLICY.COLLECTION_KEYS.AUTOREPORTING),
   163                        },
   164                    ]
   165                  : []),
   166              {
   167                  icon: Illustrations.Approval,
   168                  title: translate('workflowsPage.addApprovalsTitle'),
   169                  subtitle: translate('workflowsPage.addApprovalsDescription'),
   170                  switchAccessibilityLabel: translate('workflowsPage.addApprovalsDescription'),
   171                  onToggle: (isEnabled: boolean) => {
   172                      Policy.setWorkspaceApprovalMode(route.params.policyID, policy?.owner ?? '', isEnabled ? CONST.POLICY.APPROVAL_MODE.BASIC : CONST.POLICY.APPROVAL_MODE.OPTIONAL);
   173                  },
   174                  subMenuItems: (
   175                      <MenuItem
   176                          title={translate('workflowsPage.approver')}
   177                          titleStyle={styles.textLabelSupportingNormal}
   178                          descriptionTextStyle={styles.textNormalThemeText}
   179                          description={policyApproverName ?? ''}
   180                          onPress={() => Navigation.navigate(ROUTES.WORKSPACE_WORKFLOWS_APPROVER.getRoute(route.params.policyID))}
   181                          shouldShowRightIcon
   182                          wrapperStyle={containerStyle}
   183                          hoverAndPressStyle={[styles.mr0, styles.br2]}
   184                          brickRoadIndicator={hasApprovalError ? CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR : undefined}
   185                      />
   186                  ),
   187                  isActive: (policy?.approvalMode === CONST.POLICY.APPROVAL_MODE.BASIC && !hasApprovalError) ?? false,
   188                  pendingAction: policy?.pendingFields?.approvalMode,
   189                  errors: ErrorUtils.getLatestErrorField(policy ?? {}, CONST.POLICY.COLLECTION_KEYS.APPROVAL_MODE),
   190                  onCloseError: () => Policy.clearPolicyErrorField(policy?.id ?? '-1', CONST.POLICY.COLLECTION_KEYS.APPROVAL_MODE),
   191              },
   192              {
   193                  icon: Illustrations.WalletAlt,
   194                  title: translate('workflowsPage.makeOrTrackPaymentsTitle'),
   195                  subtitle: translate('workflowsPage.makeOrTrackPaymentsDescription'),
   196                  switchAccessibilityLabel: translate('workflowsPage.makeOrTrackPaymentsDescription'),
   197                  onToggle: (isEnabled: boolean) => {
   198                      let newReimbursementChoice;
   199                      if (!isEnabled) {
   200                          newReimbursementChoice = CONST.POLICY.REIMBURSEMENT_CHOICES.REIMBURSEMENT_NO;
   201                      } else if (!!policy?.achAccount && !Policy.isCurrencySupportedForDirectReimbursement(policy?.outputCurrency ?? '')) {
   202                          newReimbursementChoice = CONST.POLICY.REIMBURSEMENT_CHOICES.REIMBURSEMENT_MANUAL;
   203                      } else {
   204                          newReimbursementChoice = CONST.POLICY.REIMBURSEMENT_CHOICES.REIMBURSEMENT_YES;
   205                      }
   206                      const newReimburserEmail = policy?.achAccount?.reimburser ?? policy?.owner;
   207                      Policy.setWorkspaceReimbursement(policy?.id ?? '-1', newReimbursementChoice, newReimburserEmail ?? '');
   208                  },
   209                  subMenuItems:
   210                      !isOffline && policy?.isLoadingWorkspaceReimbursement === true ? (
   211                          <ActivityIndicator
   212                              size={CONST.ACTIVITY_INDICATOR_SIZE.LARGE}
   213                              color={theme.spinner}
   214                              style={styles.mt7}
   215                          />
   216                      ) : (
   217                          <>
   218                              <MenuItem
   219                                  titleStyle={shouldShowBankAccount ? styles.textLabelSupportingNormal : styles.textLabelSupportingEmptyValue}
   220                                  descriptionTextStyle={styles.textNormalThemeText}
   221                                  title={shouldShowBankAccount ? translate('common.bankAccount') : translate('workflowsPage.connectBankAccount')}
   222                                  description={bankDisplayName}
   223                                  disabled={isOffline || !isPolicyAdmin}
   224                                  shouldGreyOutWhenDisabled={!policy?.pendingFields?.reimbursementChoice}
   225                                  onPress={() => {
   226                                      if (!Policy.isCurrencySupportedForDirectReimbursement(policy?.outputCurrency ?? '')) {
   227                                          setIsCurrencyModalOpen(true);
   228                                          return;
   229                                      }
   230                                      navigateToBankAccountRoute(route.params.policyID, ROUTES.WORKSPACE_WORKFLOWS.getRoute(route.params.policyID));
   231                                  }}
   232                                  shouldShowRightIcon={!isOffline && isPolicyAdmin}
   233                                  wrapperStyle={containerStyle}
   234                                  hoverAndPressStyle={[styles.mr0, styles.br2]}
   235                              />
   236                              {shouldShowBankAccount && (
   237                                  <OfflineWithFeedback
   238                                      pendingAction={policy?.pendingFields?.reimburser}
   239                                      shouldDisableOpacity={isOffline && !!policy?.pendingFields?.reimbursementChoice && !!policy?.pendingFields?.reimburser}
   240                                      errors={ErrorUtils.getLatestErrorField(policy ?? {}, CONST.POLICY.COLLECTION_KEYS.REIMBURSER)}
   241                                      onClose={() => Policy.clearPolicyErrorField(policy?.id ?? '', CONST.POLICY.COLLECTION_KEYS.REIMBURSER)}
   242                                      errorRowStyles={[styles.ml7]}
   243                                  >
   244                                      <MenuItem
   245                                          titleStyle={styles.textLabelSupportingNormal}
   246                                          descriptionTextStyle={styles.textNormalThemeText}
   247                                          title={translate('workflowsPayerPage.title')}
   248                                          description={displayNameForAuthorizedPayer}
   249                                          onPress={() => Navigation.navigate(ROUTES.WORKSPACE_WORKFLOWS_PAYER.getRoute(route.params.policyID))}
   250                                          shouldShowRightIcon
   251                                          wrapperStyle={[...containerStyle, styles.mt0]}
   252                                          hoverAndPressStyle={[styles.mr0, styles.br2]}
   253                                          brickRoadIndicator={hasReimburserError ? CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR : undefined}
   254                                      />
   255                                  </OfflineWithFeedback>
   256                              )}
   257                          </>
   258                      ),
   259                  isEndOptionRow: true,
   260                  isActive: policy?.reimbursementChoice !== CONST.POLICY.REIMBURSEMENT_CHOICES.REIMBURSEMENT_NO,
   261                  pendingAction: policy?.pendingFields?.reimbursementChoice,
   262                  errors: ErrorUtils.getLatestErrorField(policy ?? {}, CONST.POLICY.COLLECTION_KEYS.REIMBURSEMENT_CHOICE),
   263                  onCloseError: () => Policy.clearPolicyErrorField(policy?.id ?? '-1', CONST.POLICY.COLLECTION_KEYS.REIMBURSEMENT_CHOICE),
   264              },
   265          ];
   266      }, [
   267          policy,
   268          route.params.policyID,
   269          styles,
   270          translate,
   271          policyApproverName,
   272          containerStyle,
   273          onPressAutoReportingFrequency,
   274          preferredLocale,
   275          canUseDelayedSubmission,
   276          displayNameForAuthorizedPayer,
   277          isOffline,
   278          isPolicyAdmin,
   279          theme,
   280      ]);
   281
   282      const renderOptionItem = (item: ToggleSettingOptionRowProps, index: number) => (
   283          <Section
   284              containerStyles={isSmallScreenWidth ? styles.p5 : styles.p8}
   285              key={`toggleSettingOptionItem-${index}`}
   286              renderTitle={() => <View />}
   287          >
   288              <ToggleSettingOptionRow
   289                  title={item.title}
   290                  titleStyle={[styles.textHeadline, styles.cardSectionTitle, styles.accountSettingsSectionTitle, styles.mb1]}
   291                  subtitle={item.subtitle}
   292                  subtitleStyle={[styles.textLabelSupportingEmptyValue]}
   293                  switchAccessibilityLabel={item.switchAccessibilityLabel}
   294                  onToggle={item.onToggle}
   295                  subMenuItems={item.subMenuItems}
   296                  isActive={item.isActive}
   297                  pendingAction={item.pendingAction}
   298                  errors={item.errors}
   299                  onCloseError={item.onCloseError}
   300              />
   301          </Section>
   302      );
   303
   304      const isPaidGroupPolicy = PolicyUtils.isPaidGroupPolicy(policy);
   305      const isLoading = !!(policy?.isLoading && policy?.reimbursementChoice === undefined);
   306
   307      return (
   308          <AccessOrNotFoundWrapper
   309              policyID={route.params.policyID}
   310              featureName={CONST.POLICY.MORE_FEATURES.ARE_WORKFLOWS_ENABLED}
   311          >
   312              <WorkspacePageWithSections
   313                  headerText={translate('workspace.common.workflows')}
   314                  icon={Illustrations.Workflows}
   315                  route={route}
   316                  guidesCallTaskID={CONST.GUIDES_CALL_TASK_IDS.WORKSPACE_WORKFLOWS}
   317                  shouldShowOfflineIndicatorInWideScreen
   318                  shouldShowNotFoundPage={!isPaidGroupPolicy || !isPolicyAdmin}
   319                  isLoading={isLoading}
   320                  shouldShowLoading={isLoading}
   321                  shouldUseScrollView
   322              >
   323                  <View style={[styles.mt3, shouldUseNarrowLayout ? styles.workspaceSectionMobile : styles.workspaceSection]}>
   324                      {optionItems.map(renderOptionItem)}
   325                      <ConfirmModal
   326                          title={translate('workspace.bankAccount.workspaceCurrency')}
   327                          isVisible={isCurrencyModalOpen}
   328                          onConfirm={confirmCurrencyChangeAndHideModal}
   329                          onCancel={() => setIsCurrencyModalOpen(false)}
   330                          prompt={translate('workspace.bankAccount.updateCurrencyPrompt')}
   331                          confirmText={translate('workspace.bankAccount.updateToUSD')}
   332                          cancelText={translate('common.cancel')}
   333                          danger
   334                      />
   335                  </View>
   336              </WorkspacePageWithSections>
   337          </AccessOrNotFoundWrapper>
   338      );
   339  }
   340
   341  WorkspaceWorkflowsPage.displayName = 'WorkspaceWorkflowsPage';
   342
   343  export default withPolicy(WorkspaceWorkflowsPage);

1  import type {StackScreenProps} from '@react-navigation/stack';
     2  import React, {useCallback, useMemo, useState} from 'react';
     3  import type {ValueOf} from 'type-fest';
     4  import FullPageNotFoundView from '@components/BlockingViews/FullPageNotFoundView';
     5  import HeaderWithBackButton from '@components/HeaderWithBackButton';
     6  import MenuItem from '@components/MenuItem';
     7  import OfflineWithFeedback from '@components/OfflineWithFeedback';
     8  import ScreenWrapper from '@components/ScreenWrapper';
     9  import SelectionList from '@components/SelectionList';
    10  import RadioListItem from '@components/SelectionList/RadioListItem';
    11  import useLocalize from '@hooks/useLocalize';
    12  import useThemeStyles from '@hooks/useThemeStyles';
    13  import * as ErrorUtils from '@libs/ErrorUtils';
    14  import * as Localize from '@libs/Localize';
    15  import Navigation from '@libs/Navigation/Navigation';
    16  import type {FullScreenNavigatorParamList} from '@libs/Navigation/types';
    17  import * as PolicyUtils from '@libs/PolicyUtils';
    18  import AccessOrNotFoundWrapper from '@pages/workspace/AccessOrNotFoundWrapper';
    19  import withPolicy from '@pages/workspace/withPolicy';
    20  import type {WithPolicyOnyxProps} from '@pages/workspace/withPolicy';
    21  import * as Policy from '@userActions/Policy/Policy';
    22  import CONST from '@src/CONST';
    23  import ROUTES from '@src/ROUTES';
    24  import type SCREENS from '@src/SCREENS';
    25  import {isEmptyObject} from '@src/types/utils/EmptyObject';
    26
    27  type AutoReportingFrequencyKey = Exclude<ValueOf<typeof CONST.POLICY.AUTO_REPORTING_FREQUENCIES>, 'instant'>;
    28  type Locale = ValueOf<typeof CONST.LOCALES>;
    29
    30  type WorkspaceAutoReportingFrequencyPageProps = WithPolicyOnyxProps & StackScreenProps<FullScreenNavigatorParamList, typeof SCREENS.WORKSPACE.WORKFLOWS_AUTO_REPORTING_FREQUENCY>;
    31
    32  type WorkspaceAutoReportingFrequencyPageItem = {
    33      text: string;
    34      keyForList: string;
    35      isSelected: boolean;
    36      footerComponent?: React.ReactNode | null;
    37  };
    38
    39  type AutoReportingFrequencyDisplayNames = Record<AutoReportingFrequencyKey, string>;
    40
    41  const getAutoReportingFrequencyDisplayNames = (locale: Locale): AutoReportingFrequencyDisplayNames => ({
    42      [CONST.POLICY.AUTO_REPORTING_FREQUENCIES.MONTHLY]: Localize.translate(locale, 'workflowsPage.frequencies.monthly'),
    43      [CONST.POLICY.AUTO_REPORTING_FREQUENCIES.IMMEDIATE]: Localize.translate(locale, 'workflowsPage.frequencies.daily'),
    44      [CONST.POLICY.AUTO_REPORTING_FREQUENCIES.WEEKLY]: Localize.translate(locale, 'workflowsPage.frequencies.weekly'),
    45      [CONST.POLICY.AUTO_REPORTING_FREQUENCIES.SEMI_MONTHLY]: Localize.translate(locale, 'workflowsPage.frequencies.twiceAMonth'),
    46      [CONST.POLICY.AUTO_REPORTING_FREQUENCIES.TRIP]: Localize.translate(locale, 'workflowsPage.frequencies.byTrip'),
    47      [CONST.POLICY.AUTO_REPORTING_FREQUENCIES.MANUAL]: Localize.translate(locale, 'workflowsPage.frequencies.manually'),
    48  });
    49
    50  function WorkspaceAutoReportingFrequencyPage({policy, route}: WorkspaceAutoReportingFrequencyPageProps) {
    51      const {translate, preferredLocale, toLocaleOrdinal} = useLocalize();
    52      const styles = useThemeStyles();
    53      const [isMonthlyFrequency, setIsMonthlyFrequency] = useState(policy?.autoReportingFrequency === CONST.POLICY.AUTO_REPORTING_FREQUENCIES.MONTHLY);
    54
    55      const onSelectAutoReportingFrequency = (item: WorkspaceAutoReportingFrequencyPageItem) => {
    56          Policy.setWorkspaceAutoReportingFrequency(policy?.id ?? '-1', item.keyForList as AutoReportingFrequencyKey);
    57          if (item.keyForList === CONST.POLICY.AUTO_REPORTING_FREQUENCIES.MONTHLY) {
    58              setIsMonthlyFrequency(true);
    59              return;
    60          }
    61          setIsMonthlyFrequency(false);
    62          Navigation.goBack();
    63      };
    64
    65      const getDescriptionText = () => {
    66          if (policy?.autoReportingOffset === undefined) {
    67              return toLocaleOrdinal(1);
    68          }
    69          if (typeof policy?.autoReportingOffset === 'number') {
    70              return toLocaleOrdinal(policy.autoReportingOffset);
    71          }
    72          if (typeof policy?.autoReportingOffset === 'string' && parseInt(policy?.autoReportingOffset, 10)) {
    73              return toLocaleOrdinal(parseInt(policy.autoReportingOffset, 10));
    74          }
    75
    76          return translate(`workflowsPage.frequencies.${policy?.autoReportingOffset}`);
    77      };
    78
    79      const monthlyFrequencyDetails = () => (
    80          <OfflineWithFeedback
    81              pendingAction={policy?.pendingFields?.autoReportingOffset}
    82              errors={ErrorUtils.getLatestErrorField(policy ?? {}, CONST.POLICY.COLLECTION_KEYS.AUTOREPORTING_OFFSET)}
    83              onClose={() => Policy.clearPolicyErrorField(policy?.id ?? '-1', CONST.POLICY.COLLECTION_KEYS.AUTOREPORTING_OFFSET)}
    84              errorRowStyles={[styles.ml7]}
    85          >
    86              <MenuItem
    87                  title={translate('workflowsPage.submissionFrequencyDateOfMonth')}
    88                  titleStyle={styles.textLabelSupportingNormal}
    89                  description={getDescriptionText()}
    90                  descriptionTextStyle={styles.textNormalThemeText}
    91                  wrapperStyle={styles.pr3}
    92                  onPress={() => Navigation.navigate(ROUTES.WORKSPACE_WORKFLOWS_AUTOREPORTING_MONTHLY_OFFSET.getRoute(policy?.id ?? ''))}
    93                  shouldShowRightIcon
    94              />
    95          </OfflineWithFeedback>
    96      );
    97
    98      const autoReportingFrequencyItems: WorkspaceAutoReportingFrequencyPageItem[] = Object.keys(getAutoReportingFrequencyDisplayNames(preferredLocale)).map((frequencyKey) => {
    99          const isSelected = policy?.autoReportingFrequency === frequencyKey;
   100
   101          return {
   102              text: getAutoReportingFrequencyDisplayNames(preferredLocale)[frequencyKey as AutoReportingFrequencyKey] || '',
   103              keyForList: frequencyKey,
   104              isSelected,
   105              footerContent: isMonthlyFrequency && frequencyKey === CONST.POLICY.AUTO_REPORTING_FREQUENCIES.MONTHLY ? monthlyFrequencyDetails() : null,
   106          };
   107      });
   108
   109      return (
   110          <AccessOrNotFoundWrapper
   111              policyID={route.params.policyID}
   112              featureName={CONST.POLICY.MORE_FEATURES.ARE_WORKFLOWS_ENABLED}
   113          >
   114              <ScreenWrapper
